<?php require_once __DIR__."/../config/app.php";require_role("Admin LP2M");$d=["name"=>"","type"=>"Penelitian","max_fund"=>"0","description"=>"","is_active"=>1];$err="";if($_SERVER["REQUEST_METHOD"]==="POST"){require_post_csrf();$d["name"]=post_string("name");$d["type"]=post_string("type");$d["max_fund"]=post_string("max_fund");$d["description"]=post_string("description");$d["is_active"]=isset($_POST["is_active"])?1:0;if(!$d["name"])$err="Nama wajib diisi.";if(!$err){$pdo->prepare("INSERT INTO schemes(name,type,max_fund,description,is_active) VALUES(?,?,?,?,?)")->execute([$d["name"],$d["type"],$d["max_fund"],$d["description"],$d["is_active"]]);flash("success","Skema ditambahkan.");redirect("index.php");}}$pageTitle="Tambah Skema";require __DIR__."/../partials/header.php";?><h3 class="fw-bold">Tambah Skema</h3><?php if($err):?><div class="alert alert-danger"><?=e($err)?></div><?php endif;?><form method="post" class="card p-4"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input class="form-control mb-3" name="name" placeholder="Nama skema" value="<?=e($d["name"])?>" required><select class="form-select mb-3" name="type"><option>Penelitian</option><option>Pengabdian</option></select><input class="form-control mb-3" type="number" name="max_fund" value="<?=e($d["max_fund"])?>" placeholder="Dana maksimal"><textarea class="form-control mb-3" name="description" placeholder="Deskripsi"><?=e($d["description"])?></textarea><label><input type="checkbox" name="is_active" checked> Aktif</label><div class="text-end mt-3"><a href="index.php" class="btn btn-light">Batal</a> <button class="btn btn-primary">Simpan</button></div></form><?php require __DIR__."/../partials/footer.php";?>